function close(){audio.play('ASSET-AUDIO-UI::cancel');session.cancelImport();lastImport=null;selectedSkill=null;if(session.phase==='blocked')return showBlocked();if(session.phase==='recovery-ready')return showRecoveryReady();if(session.phase==='room-recovered')return showRoomRecovered();if(session.phase==='readonly')return showReadonly();if(session.phase==='rollback-ready'&&restoringSilver)return showSilverRestored();if(!gameState())return showCreation();modal.close();panel='';pendingInteraction=null;lastFrame=0}
