function onSession(){const phase=session.phase;if(sound&&phase==='ready')syncAudioRegion();if(phase!=='ready')audio.resetObservation();if(phase==='ready'&&session.layoutNotice){toast(session.layoutNotice);session.layoutNotice=null;}if(phase==='ready'&&lastSessionPhase!=='ready')renderer.snap(gameState());lastSessionPhase=phase;const loading=['loading','catchup','paused'].includes(phase);$('#loading').hidden=!loading;$('#loadingText').textContent=phase==='paused'?'已暫停。尚未結算時間完整保留。':phase==='catchup'?`離線旅途結算 ${Math.floor((session.progress?.processed||0)/Math.max(1,session.progress?.total||1)*100)}%`:'讀取旅途…';$('#progress').value=(session.progress?.processed||0)/Math.max(1,session.progress?.total||1);$('#pause').hidden=!['catchup','paused'].includes(phase);$('#pause').textContent=phase==='paused'?'繼續結算':'暫停結算';if(loading&&modal.open)modal.close();if(phase==='blocked')showBlocked();if(phase==='recovery-ready')showRecoveryReady();if(phase==='room-recovered')showRoomRecovered();if(phase==='rollback-ready'&&restoringSilver)showSilverRestored();else if(phase==='rollback-ready')show('rollbackReady',heading('舊快照已還原，遊戲已停止')+'<p>沒有執行離線結算或自動狩獵。保存時間從此次還原起算，放棄該備份至今的離線結算。</p><p>現在請關閉所有遊戲分頁、停止伺服器，套用對應ROLLBACK程式，再用原網址開啟。完成前不要重新整理階段2。</p>');if(phase==='creation'&&panel!=='creation'&&!session.pendingImport)showCreation();if(phase==='readonly'&&panel!=='readonly'&&panel!=='export')showReadonly();if(phase==='ready'&&panel==='readonly'){modal.close();panel='';}if(!loading&&session.pendingImport&&(session.pendingImport!==lastImport||!modal.open)){lastImport=session.pendingImport;showImport()}if(phase==='ready'&&session.report&&session.report!==reportShown&&!session.pendingImport){reportShown=session.report;showReport()}updateHUD()}
