function roomStatusText(){
 if(!room?.active)return room?.reason||'尚未連線';
 const status=room.status,label={connecting:'正在連線',active:'共同冒險中',ending:'正在保存並離房'}[status.phase];
 return `${label} · 房號 ${status.code||'建立中'} · ${status.members.length} / 10 人\n${status.members.map(member=>member.name+(member.id==='host'?'（房主）':'')).join('、')}\n${status.saved?'這部裝置已保存第 '+status.saved+' 次成果':'等待首次保存'}`;
}
function showRoom(){
 const active=room?.active;
 show('room',heading('家庭連線')+'<p>每人使用自己的手機與選中的一名角色，最多十人。這部手機其餘角色在家庭房期間暫停。請連同一個 Wi-Fi，並保持遊戲在前景。</p><p>開房會建立新世界；本人或同伴攻擊、替參戰者補血都算參與；參與者均分經驗；普通怪每堆掉落物隨機分一人，Boss 每名參戰者各有一般戰利品並至少可獲得金幣，個人任務保留。離房回到各自進房前的位置。房主離開時房間結束，各自保留已保存成果。</p><p>首次開戰以同圖房員數鎖定倍率：1／2／3／4／5／6–10 人為 1／1.5／2.5／3.5／4.5／5 倍，增加怪物生命、攻擊與物理防護，整隊總經驗及掉落同步增加；不是每人各乘一次。</p>'+`<p id="roomStatus" role="status" style="white-space:pre-line">${escape(roomStatusText())}</p>`+(active?'<button data-action="leaveRoom">保存並離開房間</button>':'<label for="signalURL">配對服務網址</label><input id="signalURL" type="url" value="/signal" placeholder="https://遊戲網址/signal"><p class="fine">使用已架設的配對服務。單獨的靜態遊戲網址尚不能開房。</p><label for="roomCode">房間號碼</label><input id="roomCode" maxlength="12" inputmode="text" autocomplete="off"><div class="actions"><button data-action="hostRoom">建立房間</button><button data-action="joinRoom">加入房間</button></div>'));
}
async function startRoom(join){
 questNavigation=null;
 if(room?.active)return;
 if(!globalThis.isSecureContext)return toast('家庭連線請使用 HTTPS 遊戲網址；電腦本機測試可使用 localhost');
 if(typeof RTCPeerConnection!=='function')return toast('這個瀏覽器不支援家庭連線，請更新瀏覽器後再試');
 const code=join?$('#roomCode').value.trim().toUpperCase():'',serverURL=$('#signalURL').value.trim();
 if(join&&!code)return toast('請輸入房間號碼');
 if(session.phase!=='ready')return toast('請先完成角色載入，再連線');
 let priorPhase='idle';
 const nextRoom=new RoomController(session,{
  onChange:status=>{if(room!==nextRoom)return;renderer.setRoomPlayers?.(companionPlayers());updateHUD();const label=$('#roomStatus');if(label)label.textContent=roomStatusText();if(status.phase==='idle'&&priorPhase!=='idle'){renderer.snap(session.state);toast(room.reason||'房間已結束，已保留確認成果')}priorPhase=status.phase;},
  onEvents:(events,state)=>{renderer.notice(events,state);},onError:error=>toast(error.message||String(error))
 });
 room=nextRoom;
 try{const starting=room.start({code,serverURL});showRoom();await starting;if(panel==='room')showRoom();}
 catch(error){toast('無法連線：'+error.message);if(panel==='room')showRoom();}
}
function creationKitHTML(classId=chosenClass,allocated=allocation){
 const c=CLASSES[classId],base=Object.fromEntries(c.stat_order.map((a,i)=>[a,c.base_stats[i]+(allocated[a]||0)]));
 const stacks={'ITEM-RED-POTION':100,'ITEM-BLUE-POTION':10,'ITEM-TELEPORT-SCROLL':100,'ITEM-RETURN-SCROLL':20,'ITEM-GREEN-POTION':30};
 const equipment=['EQ-DAGGER','EQ-LEATHER-ARMOR'],total=equipment.reduce((n,id)=>n+ITEMS[id].weight,0)+Object.entries(stacks).reduce((n,[id,count])=>n+ITEMS[id].weight*count,0),capacity=500+50*base.STR+30*base.CON,ratio=total/capacity;
 return '<h3>新旅程物資</h3><p>出生於銀騎士村。'+equipment.map(id=>itemTitle({itemId:id,identified:true,plus:0})+' × 1（已鑑定）').join('、')+'。</p><p>'+Object.entries(stacks).map(([id,count])=>escape(ITEMS[id].name_zh)+' × '+count).join('、')+'。</p><p>不額外贈送技能；技能書需取得後手動學習。物資只在建立新角色時發放。</p>'+`<div class="notice ${ratio>=.5?'warn':''}">起始負重 ${total} / ${capacity}（${(ratio*100).toFixed(1)}%）。${ratio>=.5?'已達50%，自然生命與魔力恢復會停止；可先到倉庫存放部分補給。':'未達50%，可自然恢復。'}</div>`;
}
