function showCreation(){const c=CLASSES[chosenClass],spent=Object.values(allocation).reduce((a,b)=>a+b,0),members=session.listCharacters();show('creation',heading(members.length?'新增旅人（'+members.length+' / 4）':'建立旅人')+`<div class="notice warn">開發測試版：部分怪物與角色外觀仍待補齊；手機操作、儲存與音訊待實機確認。新增玩法採試玩規格，仍需實際遊玩驗收。</div><p class="muted">四種職業，從普通攻擊開始。</p>${creationKitHTML()}<div class="classes">${Object.entries(CLASSES).map(([id,c])=>`<button data-class="${id}" class="${id===chosenClass?'selected':''}">${c.name_zh}</button>`).join('')}</div><p>${c.role}</p><p>尚有 ${c.creation_bonus-spent} 點可分配</p><div class="attributes">${c.stat_order.map((a,i)=>`<div class="attribute"><label>${attrNames[a]} <small>${a}</small></label><button data-attr="${a}" data-delta="-1" ${!(allocation[a]>0)?'disabled':''}>−</button><b>${c.base_stats[i]+(allocation[a]||0)}</b><button data-attr="${a}" data-delta="1" ${spent>=c.creation_bonus||c.base_stats[i]+(allocation[a]||0)>=c.creation_caps[a]?'disabled':''}>+</button></div>`).join('')}</div><div class="actions"><button data-action="recommended">建議配點</button><button data-action="sound">${sound?'關閉音訊':'開啟音訊'}</button></div><label for="newName">旅人的名字</label><input id="newName" maxlength="20" value="${escape(creationName)}" placeholder="旅人"><div class="actions"><button class="primary" data-action="create" ${spent!==c.creation_bonus?'disabled':''}>開始新旅程</button><button data-action="import">匯入備份</button></div>${session.legacy.length?'<button data-action="legacy">檢視與匯出既有角色</button>':''}<p class="fine">新版採用不同世界與成長規則；既有角色不會自動轉換或清除。</p>`)}
function showCharacter(){const s=gameState(),p=s.player,st=stats(s),w=weight(s),earned=BigInt(p.totalXP)-xpAtLevel(p.level),required=xpNeeded(p.level),xpPercent=Number(earned*10000n/required)/100;show('character',heading(p.name+' · '+CLASSES[p.classId].name_zh)+'<button data-action="characters">切換角色／本機組隊</button>'+`<div class="stats">${[['等級',p.level],['總經驗',p.totalXP],['AC',st.ac],['MR',st.mr],['負重',`${w.total.toFixed(1)} / ${w.capacity}`],['金幣',p.gold]].map(([k,v])=>`<div class="stat"><small>${k}</small><b>${escape(v)}</b></div>`).join('')}</div><div class="progress-label">本級經驗 ${earned.toString()} / ${required.toString()} · ${xpPercent.toFixed(2)}%</div><div class="stat-progress xp-progress" role="progressbar" aria-label="本級經驗" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${xpPercent}"><i style="width:${xpPercent}%"></i></div><div class="progress-label">負重 ${(w.ratio*100).toFixed(1)}% · 50%停止自然恢復／80%移動變慢</div><div class="stat-progress weight-progress" role="progressbar" aria-label="負重" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,w.ratio*100)}"><i style="width:${Math.min(100,w.ratio*100)}%;background:${w.ratio>=.5?'#996948':'#708064'}"></i><em style="left:50%"></em><em style="left:80%"></em></div><p>物理攻擊加成 ${st.damage-st.collection.damage} <span class="collection-bonus">(+${st.collection.damage})</span> · 命中 ${st.hit-st.collection.hit} <span class="collection-bonus">(+${st.collection.hit})</span><br>目前變身攻速倍率 ×${st.formSpeed}</p><h3>六項屬性</h3><div class="attributes">${ATTRS.map(a=>`<div class="attribute"><label>${attrNames[a]}</label><b>${st.attrs[a]}</b>${availablePoints(s)?`<button data-grow="${a}">＋</button>`:''}</div>`).join('')}</div><p>可分配成長點數 ${availablePoints(s)}。51 級起，每升一級一點。</p><div class="notice">${w.ratio>=1?'負重達100%，無法移動、攻擊、施法或拾取。':w.ratio>=.8?'負重達80%，移動變慢，自然恢復停止。':w.ratio>=.5?'負重達50%，自然生命與魔力恢復停止。':'負重未達50%，可自然恢復。'}<br>飽食 ${p.food}/100</div>`)}
const itemName=equipmentName;
function itemTitle(item,label=itemName(item)){return `<strong class="item-name" data-quality="${itemQuality(item)}">${escape(label)}</strong>${enchantmentHTML(item)}`}
function weaponArtPending(item){if(item.slot!=='weapon'||!renderer.stanceIndex||!item.class_restrictions?.includes(gameState().player.classId))return false;const row=renderer.stanceIndex.classes?.[CONTENT.classes[gameState().player.classId]],binding=row?.items?.[item.id]||row?.families?.[item.family];return !binding||!['accepted-default','source-reviewed-candidate','integration-candidate'].includes(binding.status)}
