function showImport(){const chosen=session.pendingImport;if(!chosen)return;if(chosen.legacy)return show('legacyImport',heading('舊版本備份')+'<p>此備份不會自動轉換。原始資料可完整匯出保留；新版須建立獨立旅程。</p><div class="actions"><button data-action="exportLegacyImport">匯出原始備份</button><button data-action="close">關閉</button></div>');const p=chosen.state.player;show('importConfirm',heading('確認匯入旅人')+`<p>${escape(p.name)} · ${CLASSES[p.classId].name_zh} · Lv.${p.level}</p><p>${escape(chosen.exportedAt||'日期未提供')}<br>進度保存時間：${new Date(chosen.resolvedAt).toLocaleString()}${chosen.resolvedAt>Date.now()?'<br>備份時間晚於本機時間，將由現在起算。':''}</p><div class="notice warn">目前新版角色會先封存，再載入這份備份。匯入後按備份中的裝備、補給與自動狩獵設定，結算保存時間以來尚未處理的離線旅途。</div><div class="actions"><button class="danger" data-action="confirmImport">確認取代並匯入</button><button data-action="close">取消</button></div>${silverRestorePreview(chosen.state)}${chosen.state.formProgress===undefined&&canRestoreBeforeSilver(chosen.state)?'<hr><h3>圖鑑升級前：階段1／122版程式</h3><p>僅供回復舊程式：原封存進度先保留；還原後停止遊戲，不結算此備份至今離線時間。</p><button data-action="prepareDowngrade">回復舊程式用：僅還原快照</button>':''}`)}
