function wildPetTraitsHTML(monster){if(!monster.petV4)return'';const pet={type:monster.petType,level:monster.level||1,v4:monster.petV4},attributes=petAttributes(pet),colors={white:'#eee',blue:'#8cc4ff',orange:'#ffb25c'};return'<p>'+(pet.v4.sex==='male'?'雄性':'雌性')+(pet.v4.shiny?' · <strong style="color:#ffe28a">異色</strong>':'')+'</p><table class="pet-attributes"><thead><tr><th>屬性</th><th>出生</th><th>目前</th><th>品質</th></tr></thead><tbody>'+Object.entries(attributes).map(([key,a])=>'<tr style="color:'+colors[a.quality]+'"><th>'+key+'</th><td>'+effectNumber(a.birth)+'</td><td>'+effectNumber(a.value)+'</td><td>'+({white:'白',blue:'藍',orange:'橘'}[a.quality])+'</td></tr>').join('')+'</tbody></table><p>個性：'+escape(petNatureText(pet.v4.nature))+'</p>'}

async function interact(hit){const s=gameState();if(!s||portraitMedia?.matches||!playable())return;if(selectedSkill){const id=selectedSkill;selectedSkill=null;const c={type:'skill',skillId:id,...skillOptions,targetId:hit.entity?.id,point:hit.kind==='ground'?{x:hit.x,y:hit.y}:hit.entity?{x:hit.entity.x,y:hit.entity.y}:undefined};await act(c);return}if(hit.kind==='ally')return toast(hit.entity.name||'同行家人');if(hit.kind==='monster'){selectedTarget=hit.entity.id;if(hit.entity.petType){const type=PETS[hit.entity.petType];return show('wild',heading(MONSTERS[hit.entity.type].name_zh)+wildPetTraitsHTML(hit.entity)+`<p>牠喜歡${ITEMS[type.favorite_food_item_id].name_zh}。餵食需要靠近，成功率受魅力與剩餘生命影響。</p><div class="actions"><button data-feed-wild="${hit.entity.id}" data-food="${type.favorite_food_item_id}">餵食</button><button data-attack="${hit.entity.id}">攻擊</button><button data-action="close">離開</button></div>`)}return act({type:'attack',targetId:hit.entity.id})}if(['corpse','summon','hero'].includes(hit.kind))return hit.kind==='hero'?showCharacter():showPets();if(hit.kind==='pet'){selectedTarget=hit.entity.id;return showPets()}if(hit.kind==='groundItem')return act({type:'pickup',id:hit.entity.id});if(['npc','connection','landmark'].includes(hit.kind)){pendingInteraction=hit;const pos=hit.kind==='npc'?{x:hit.entity.position_tiles[0],y:hit.entity.position_tiles[1]}:hit.kind==='connection'?crossing(hit.entity.id,s.player.map).entrance:{x:hit.entity.tile_x,y:hit.entity.tile_y};if(distance(s.player,pos)<=(hit.kind==='connection'?1:2))return finishInteraction();return act({type:'move',...pos})}return act({type:'move',x:hit.x,y:hit.y})}
async function finishInteraction(){const hit=pendingInteraction;if(!hit)return;pendingInteraction=null;if(hit.kind==='npc'){const r=await act({type:'talk',npcId:hit.entity.id});if(r.ok)showNPC(hit.entity.id)}else if(hit.kind==='landmark'){const r=await act({type:'survey',landmarkId:hit.entity.id});if(r.ok)toast('已記錄地標：'+hit.entity.name_zh)}else{const conn=hit.entity,cross=crossing(conn.id,gameState().player.map),fare=conn.transport_parameters;show('travel',heading(MAPS[cross.mapId].name_zh)+`<p>${fare?`船資 ${fare.fare_each_way} 金幣；每 ${fare.departure_interval_game_seconds/60} 分鐘一班，航程 ${fare.transit_seconds/60} 分鐘。`:'從這裡進入相鄰地區。'}</p><button class="primary" data-travel="${conn.id}">${fare?'付費登船':'通過入口'}</button>`)}}
const pointers=new Map;let gesture=null;
canvas.addEventListener('pointerdown',e=>{if(modal.open||portraitMedia?.matches||!playable())return;unlockAudio();pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});canvas.setPointerCapture(e.pointerId);gesture={id:e.pointerId,startX:e.clientX,startY:e.clientY,lastX:e.clientX,lastY:e.clientY,moved:false};if(pointers.size>=2){const [a,b]=[...pointers.values()];gesture={pinch:Math.hypot(a.x-b.x,a.y-b.y),scale:renderer.scale,moved:true}}});
canvas.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId)||!gesture)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size>=2){const[a,b]=[...pointers.values()];if(gesture.pinch)renderer.scale=Math.max(.6,Math.min(1.4,gesture.scale*Math.hypot(a.x-b.x,a.y-b.y)/gesture.pinch));return}if(gesture.id!==e.pointerId)return;if(Math.hypot(e.clientX-gesture.startX,e.clientY-gesture.startY)>12)gesture.moved=true;gesture.lastX=e.clientX;gesture.lastY=e.clientY});
canvas.addEventListener('pointerup',e=>{const g=gesture;pointers.delete(e.pointerId);gesture=null;if(g&&!g.moved&&g.id===e.pointerId&&!modal.open&&playable()){const r=canvas.getBoundingClientRect();interact(renderer.hit(gameState(),e.clientX-r.left,e.clientY-r.top,selectedSkill?SKILLS[selectedSkill].target:null)).catch(e=>toast(e.message))}});for(const type of ['pointercancel','lostpointercapture'])canvas.addEventListener(type,e=>{pointers.delete(e.pointerId);gesture=null});
