function resize(){const v=window.visualViewport;document.documentElement.style.setProperty('--visual-height',(v?.height||innerHeight)+'px');document.documentElement.style.setProperty('--visual-top',(v?.offsetTop||0)+'px');renderer.resize();syncOrientation()}window.addEventListener('resize',resize);portraitMedia?.addEventListener('change',()=>{gesture=null;pointers.clear();syncOrientation()});window.visualViewport?.addEventListener('resize',resize);window.visualViewport?.addEventListener('scroll',resize);resize();
