async function resume(offline=true){if(resuming||room?.active)return;resuming=true;try{while(session.busy)await new Promise(r=>setTimeout(r,10));await session.queue;if(!offline)await session.checkpoint();await session.catchUp({offline})}finally{audio.resetObservation();resuming=false;lastFrame=0}}
document.addEventListener('visibilitychange',()=>{gesture=null;pointers.clear();lastFrame=0;if(room?.active){if(document.hidden)room.leave('遊戲切到背景，連線已結束').catch(e=>toast(e.message));return}if(document.hidden){session.checkpoint()}else if(gameState())resume(true)});window.addEventListener('pagehide',()=>{if(room?.active)room.leave('遊戲頁面已離開').catch(()=>{});else session.checkpoint()});window.addEventListener('pageshow',e=>{resize();if(e.persisted&&gameState())resume(true)});
function frame(t){requestAnimationFrame(frame);advanceQuestNavigation();renderer.setRoomPlayers?.(companionPlayers());renderer.draw(gameState(),t);if(room?.active){if(sound&&playable())audio.observe(gameState());if(playable()&&pendingInteraction&&!gameState().player.path.length)finishInteraction().catch(e=>toast(e.message));if(t-lastUI>150){updateHUD();lastUI=t}lastFrame=0;return}if(session.phase!=='ready'||session.busy||resuming||document.hidden){audio.resetObservation();lastFrame=0;return}const gap=Math.max(0,(Date.now()-session.stateWallAt)/1000);if(gap>.35){resume(false);return}const events=session.tick(gap);if(sound)audio.observe(gameState());if(events.length){renderer.notice(events,gameState());for(const e of events)if(['death','capture','fusion','map','formUnlock'].includes(e.type))logs.push(e.type==='formUnlock'?'收藏圖鑑：'+(formDefinition(e.formId)?.name_zh||e.formId):e.type==='death'?'你倒下了，等待城鎮復活。':e.type==='capture'?'獲得新的同行夥伴。':e.type==='fusion'?'融合結果已產生。':'抵達 '+MAPS[e.mapId].name_zh);logs=logs.slice(-3);$('#messageLog').textContent=logs.join('\n');}if(pendingInteraction&&!gameState().player.path.length){finishInteraction().catch(e=>toast(e.message))}if(t-lastUI>150){updateHUD();lastUI=t}if(t-lastSave>2000){lastSave=t;session.checkpoint()}lastFrame=t}
requestAnimationFrame(frame);
